    results = {}
    Z_values = [5, 9]
    X_range = range(2, 11)

    print("--- Starting Calculation ---")

    for z in Z_values:
        results[z] = {}
        print(f"\nProcessing z = {z}")

        for x in X_range:
            try:
                # 1. Calculate P(x) = (x^z + 1) / (x + 1)
                # We use integer exponentiation, which is safe for these small ranges.
                x_z_plus_1 = pow(x, z) + 1
                x_plus_1 = x + 1
                P_x = x_z_plus_1 // x_plus_1

                if P_x == 0:
                    print(f"Warning: P({x}) for z={z} is 0. Skipping.")
                    continue

                # 2. Get prime factorizations
                factors_P = get_prime_factorization(P_x)
                factors_X_plus_1 = get_prime_factorization(x_plus_1)

                # 3. Check the necessary condition: every prime factor of P(x) must divide x+1.
                condition_holds = True
                for p in factors_P:
                    if p not in factors_X_plus_1:
                        condition_holds = False
                        break

                if condition_holds:
                    print(f"  x={x}: Condition holds. P(x) = {P_x}. x+1 = {x_plus_1}.")

                    # 4. Determine minimum required exponent k = y-1
                    max_ratio = 0.0

                    for p, e_P in factors_P.items():
                        e_X_plus_1 = factors_X_plus_1[p]

