                        ratio = e_P / e_X_plus_1
                        if ratio > max_ratio:
                            max_ratio = ratio

                    # k is the minimum required exponent for y-1
                    k_min = math.ceil(max_ratio)

                    # y_min = k_min + 1
                    y_min = int(k_min) + 1

